SELECT w.w_warehouse_name, SUM(cr.cr_return_amount) AS total_return_amount, SUM(ss.ss_net_paid) AS total_sales_net_paid, SUM(cr.cr_net_loss) AS total_net_loss, CASE WHEN SUM(ss.ss_net_paid) > 0 THEN SUM(cr.cr_net_loss) / SUM(ss.ss_net_paid) ELSE NULL END AS net_loss_ratio, CASE WHEN SUM(ss.ss_net_paid) > 0 THEN CASE WHEN SUM(cr.cr_net_loss) / SUM(ss.ss_net_paid) > 0.1 THEN 'High Loss' ELSE 'Low Loss' END ELSE 'No Sales' END AS loss_category, DENSE_RANK() OVER (ORDER BY CASE WHEN SUM(ss.ss_net_paid) > 0 THEN SUM(cr.cr_net_loss) / SUM(ss.ss_net_paid) ELSE NULL END DESC) AS loss_ratio_rank FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk JOIN store_sales ss ON ss.ss_item_sk = cr.cr_item_sk AND ss.ss_sold_date_sk = cr.cr_returned_date_sk JOIN time_dim t_cr ON cr.cr_returned_time_sk = t_cr.t_time_sk JOIN time_dim t_ss ON ss.ss_sold_time_sk = t_ss.t_time_sk GROUP BY w.w_warehouse_name ORDER BY net_loss_ratio DESC
